properties.property:
local BlockPlayer = require "actions/BlockPlayer"
local DialogueChoice = require "actions/DialogueChoice"

return function(self)
    return BlockPlayer {
         DialogueChoice(
            "Nicole: What would you like me to do, Sally?",
            {
                {"Turn Off Magnets",
                    function(menu)
                        menu:close()

                        self.scene.magnetsOn = false
                        self.scene.objectLookup.MagnetCollision:removeCollision()
                    end},
                {"Do Nothing",
                    function(menu)
                        menu:close()
                    end}
            }
        )
    }
end
